insert into public.programming_lessons
(id,module_id,title,summary,content_md,duration_minutes,sort_order,published)
values
('web-09-js-types-operators','web-foundations','أنواع البيانات والعمليات في JavaScript','تعرّف على النصوص والأرقام والقيم المنطقية والتحويلات والمقارنات.',
E'## أنواع البيانات\nتتعامل JavaScript مع أنواع أساسية مثل النصوص والأرقام والقيم المنطقية:\n\n```javascript\nconst student = "Mona";\nconst lessons = 8;\nconst isActive = true;\nlet result;\n\nconsole.log(typeof student);\nconsole.log(typeof lessons);\nconsole.log(typeof isActive);\nconsole.log(typeof result);\n```\n\n## العمليات والمقارنة\n```javascript\nconst total = 12 + 5;\nconst remainder = 17 % 3;\nconst isEqual = (5 === "5");\nconsole.log(total, remainder, isEqual);\n```\n\nاستخدم === للمقارنة الصارمة التي تراعي النوع والقيمة. تجنب الاعتماد على التحويل التلقائي غير الواضح.\n\n## تدريب\nأنشئ متغيرين رقميين، احسب المجموع والمتوسط، ثم قارن هل المتوسط أكبر من 50.',16,9,true),
('web-10-js-conditions','web-foundations','الشروط واتخاذ القرار في JavaScript','استخدم if وelse وswitch لاختيار ما ينفذه البرنامج.',
E'## if وelse\n```javascript\nconst score = 82;\n\nif (score >= 85) {\n  console.log("Excellent");\n} else if (score >= 50) {\n  console.log("Passed");\n} else {\n  console.log("Try again");\n}\n```\n\n## switch\n```javascript\nconst day = "Monday";\n\nswitch (day) {\n  case "Monday":\n    console.log("Start of the week");\n    break;\n  case "Friday":\n    console.log("Weekend");\n    break;\n  default:\n    console.log("Another day");\n}\n```\n\n## تدريب\nاكتب برنامجًا يستقبل درجة من 0 إلى 100 ويطبع تقديرًا مناسبًا. أضف حالة تتعامل مع الدرجات غير الصحيحة.',16,10,true),
('web-11-js-loops','web-foundations','الحلقات والتكرار في JavaScript','استخدم for وwhile لتكرار الأوامر والتحكم في عدد مرات التنفيذ.',
E'## حلقة for\n```javascript\nfor (let number = 1; number <= 5; number++) {\n  console.log(number);\n}\n```\n\n## حلقة while\n```javascript\nlet counter = 1;\nwhile (counter <= 3) {\n  console.log("Attempt", counter);\n  counter++;\n}\n```\n\n## for...of\n```javascript\nconst topics = ["HTML", "CSS", "JavaScript"];\nfor (const topic of topics) {\n  console.log(topic);\n}\n```\n\n## تدريب\nاطبع الأعداد الزوجية من 2 إلى 20، ثم احسب مجموعها باستخدام متغير تجميعي.',16,11,true),
('web-12-js-arrays','web-foundations','المصفوفات Arrays','اجمع عدة قيم في مصفوفة وتعلم الوصول إلى عناصرها وتعديلها.',
E'## إنشاء مصفوفة\n```javascript\nconst skills = ["HTML", "CSS", "JavaScript"];\nconsole.log(skills[0]);\nconsole.log(skills.length);\n```\n\n## إضافة وحذف عناصر\n```javascript\nconst tasks = ["Read", "Practice"];\ntasks.push("Build");\nconst lastTask = tasks.pop();\nconsole.log(tasks, lastTask);\n```\n\n## المرور على العناصر\n```javascript\nconst prices = [10, 20, 30];\nfor (const price of prices) {\n  console.log(price);\n}\n```\n\n## تدريب\nأنشئ مصفوفة من خمسة أسماء دروس، ثم اطبع عددها وكل اسم بالترتيب. أضف درسًا جديدًا واحذف آخر عنصر.',17,12,true),
('web-13-js-objects','web-foundations','الكائنات Objects','مثّل البيانات المرتبطة باستخدام الخصائص والقيم داخل كائن.',
E'## إنشاء كائن\n```javascript\nconst course = {\n  title: "Web Development",\n  lessons: 16,\n  active: true\n};\n\nconsole.log(course.title);\nconsole.log(course.lessons);\n```\n\n## تعديل خاصية\n```javascript\ncourse.lessons = 17;\ncourse.level = "Beginner";\nconsole.log(course);\n```\n\n## مصفوفة من الكائنات\n```javascript\nconst students = [\n  { name: "Mona", score: 90 },\n  { name: "Omar", score: 84 }\n];\n\nfor (const student of students) {\n  console.log(student.name, student.score);\n}\n```\n\n## تدريب\nأنشئ كائنًا يمثل كتابًا يحتوي على العنوان والمؤلف وعدد الصفحات، ثم اطبع جملة تلخص بياناته.',17,13,true),
('web-14-js-functions-scope','web-foundations','الدوال ونطاق المتغيرات','اكتب دوالًا تستقبل معاملات وتعيد نتائج وافهم نطاق المتغيرات.',
E'## دالة تعيد قيمة\n```javascript\nfunction calculateTotal(price, quantity) {\n  return price * quantity;\n}\n\nconst total = calculateTotal(25, 3);\nconsole.log(total);\n```\n\n## Arrow Function\n```javascript\nconst double = (number) => number * 2;\nconsole.log(double(6));\n```\n\n## نطاق المتغيرات\nالمتغير المعرّف داخل دالة باستخدام let أو const يكون متاحًا داخل نطاق الدالة فقط. اختر أسماء واضحة وتجنب إنشاء متغيرات عامة بلا حاجة.\n\n## تدريب\nاكتب دالة تحسب متوسط ثلاثة أرقام، ثم دالة أخرى تحدد هل الناتج أكبر من أو يساوي 50.',18,14,true),
('web-15-js-forms-validation','web-foundations','النماذج والتحقق من المدخلات','اقرأ قيمة حقل نموذج وتحقق من وجودها قبل عرض النتيجة.',
E'## نموذج بسيط\n```html\n<form id="nameForm">\n  <label for="studentName">اسمك</label>\n  <input id="studentName" name="studentName" required>\n  <button type="submit">إرسال</button>\n</form>\n<p id="formMessage" aria-live="polite"></p>\n```\n\n## التعامل مع الإرسال\n```javascript\nconst form = document.querySelector("#nameForm");\nconst nameInput = document.querySelector("#studentName");\nconst message = document.querySelector("#formMessage");\n\nform.addEventListener("submit", function (event) {\n  event.preventDefault();\n  const name = nameInput.value.trim();\n  if (!name) {\n    message.textContent = "اكتب اسمك أولًا.";\n    return;\n  }\n  message.textContent = "أهلًا " + name;\n});\n```\n\n## ملاحظات مهمة\nاستخدم label مرتبطًا بالحقل، وخصائص HTML مثل required وtype لتسهيل الإدخال. لا تعتمد على تحقق المتصفح وحده عند بناء تطبيق حقيقي؛ يجب التحقق من البيانات على الخادم أيضًا.\n\n## تدريب\nأنشئ نموذجًا يستقبل اسم مشروع وفكرته، ثم يعرض رسالة تأكيد بعد التأكد من أن الحقلين غير فارغين.',20,15,true),
('web-16-js-mini-project','web-foundations','مشروع تطبيقي: قائمة مهام صغيرة','اجمع HTML وCSS وJavaScript لبناء قائمة مهام تفاعلية.',
E'## هيكل HTML\n```html\n<h1>قائمة مهامي</h1>\n<form id="taskForm">\n  <label for="taskInput">مهمة جديدة</label>\n  <input id="taskInput" required>\n  <button type="submit">إضافة</button>\n</form>\n<ul id="taskList"></ul>\n```\n\n## JavaScript\n```javascript\nconst taskForm = document.querySelector("#taskForm");\nconst taskInput = document.querySelector("#taskInput");\nconst taskList = document.querySelector("#taskList");\n\ntaskForm.addEventListener("submit", function (event) {\n  event.preventDefault();\n  const title = taskInput.value.trim();\n  if (!title) return;\n\n  const item = document.createElement("li");\n  item.textContent = title;\n  taskList.appendChild(item);\n  taskInput.value = "";\n  taskInput.focus();\n});\n```\n\n## تحسينات CSS مقترحة\nاجعل القائمة داخل بطاقة، وأضف مسافة بين المهام وحدودًا خفيفة للحقول والأزرار. اختبر الصفحة على شاشة هاتف.\n\n## تحديات إضافية\n1. أضف زرًا بجانب كل مهمة لحذفها.\n2. أضف إمكانية وضع علامة على المهمة المكتملة.\n3. أظهر رسالة عندما تكون القائمة فارغة.\n\n## ما الذي تعلمته؟\nاستخدمت عناصر HTML، ونموذجًا، ومحددات DOM، والأحداث، وإنشاء العناصر وإضافتها إلى الصفحة.',25,16,true)
on conflict(id) do nothing;